import importlib.util
import sys

def load_extension(file_path, base_pythonpath, root_directory):
    try:
        spec = importlib.util.spec_from_file_location("extension", file_path)
        if not spec:
            raise ImportError(f"Could not load extension from {file_path}")

        extension_module = importlib.util.module_from_spec(spec)
        sys.modules["extension"] = extension_module
        spec.loader.exec_module(extension_module)

        if hasattr(extension_module, "Extend"):
            return extension_module.Extend(base_pythonpath, root_directory)
        else:
            raise AttributeError("Extension module does not define an 'Extend' function")
    except Exception as e:
        print(f"Error loading or executing extension: {e}")
        return None
