import os

class FileRevisionsManager:
    def __init__(self, directory):
        self.directory = directory

    def create_file(self, filename, content=''):
        filepath = os.path.join(self.directory, filename)
        with open(filepath, 'w') as f:
            f.write(content)

    def read_file(self, filename):
        filepath = os.path.join(self.directory, filename)
        if os.path.exists(filepath):
            with open(filepath, 'r') as f:
                return f.read()
        else:
            return None

    def merge_changes(self, source_filename, target_filename):
        source_path = os.path.join(self.directory, source_filename)
        target_path = os.path.join(self.directory, target_filename)

        if not os.path.exists(target_path):
            self.create_file(target_filename, self.read_file(source_filename))
        else:
            with open(target_path, 'a') as target_file:
                source_content = self.read_file(source_filename)
                target_file.write('\n' + source_content)


# Usage
