    manager.create_file('hello.txt', 'Initial version')
    print(manager.read_file('hello.txt'))
    manager.create_file('updates.txt', 'Updated version')
    manager.merge_changes('updates.txt', 'hello.txt')
    print(manager.read_file('hello.txt'))
