import os

class PackageManager:
    def __init__(self):
        self.repositories = {}

    def add_repository(self, repo_url, package_manager=None):
        if not package_manager:
            if repo_url.endswith('.deb'):
                package_manager = 'apt'
            elif repo_url.endswith('.rpm'):
                package_manager = 'yum'
        self.repositories[repo_url] = package_manager

    def install_package(self, package_name):
        for repo, pm in self.repositories.items():
            try:
                if pm == 'apt':
                    command = f'sudo apt-get update && sudo apt-get install -y {package_name}'
                elif pm == 'yum':
                    command = f'sudo yum install -y {package_name}'
                result = subprocess.run(command, shell=True, check=True)
                return result
            except subprocess.CalledProcessError as e:
                print(f"Failed to install {package_name} from {repo}. Error: {e}")
        raise Exception(f"{package_name} could not be installed from any of the configured repositories.")

# Example usage:
manager = PackageManager()
manager.add_repository('http://example.com/deb-packages', 'apt')
manager.add_repository('http://example.com/rpm-packages', 'yum')
try:
    manager.install_package('example-package')
except Exception as e:
