class CodeComplexityAnalyzer:
    def __init__(self, max_lines=100, max_complexity=5):
        self.max_lines = max_lines
        self.max_complexity = max_complexity

    def analyze_file(self, file_path):
        tree = self.parse_file(file_path)
        results = self.visit_tree(tree)
        return results

    def parse_file(self, file_path):
        with open(file_path, 'r') as file:
            tree = ast.parse(file.read())
        return tree

    def visit_tree(self, node):
        visitor = NodeVisitor(self)
        return visitor.visit(node)

    def get_report(self, files_to_analyze):
        results = []
        for file_path in files_to_analyze:
            if file_path.endswith('.py'):
                result = self.analyze_file(file_path)
                results.append(result)
        return results

class NodeVisitor(ast.NodeVisitor):
    def __init__(self, analyzer):
        super().__init__()
        self.analyzer = analyzer
        self.results = []

    def visit_FunctionDef(self, node):
        method_name = node.name
        lines_of_code = len(node.body)
        complexity = self.calculate_complexity(node)
        if lines_of_code > self.analyzer.max_lines or complexity > self.analyzer.max_complexity:
            self.results.append((method_name, lines_of_code, complexity))
        self.generic_visit(node)

    def calculate_complexity(self, node):
