        self.complexity += 1
        self.generic_visit(node)

    def visit_While(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_TryExcept(self, node):
        self.complexity += 1
        self.generic_visit(node)

    def visit_TryFinally(self, node):
        self.complexity += 1
        self.generic_visit(node)

