                            self.stats['info_count'] += 1
                        elif self._is_error(line):
                            self.stats['error_count'] += 1
                        elif self._is_warning(line):
                            self.stats['warning_count'] += 1

    def _is_info(self, line):
        # Implement regex pattern matching for info level logs
        pattern = r'\bINFO\b'
        return bool(re.search(pattern, line))

    def _is_error(self, line):
        # Implement regex pattern matching for error level logs
        pattern = r'\bERROR\b'
        return bool(re.search(pattern, line))

    def _is_warning(self, line):
        # Implement regex pattern matching for warning level logs
        pattern = r'\bWARNING\b'
        return bool(re.search(pattern, line))

