import requests
from bs4 import BeautifulSoup
import time

def download_page(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        return soup
    except Exception as e:
        print(f"Error downloading {url}: {e}")
        return None

def save_page(soup, filename):
    if soup:
        with open(filename, 'w', encoding='utf-8') as file:
            file.write(str(soup))
        print(f"Saved {filename}")

def crawl_pages(seed_urls, max_depth=2):
    visited_urls = set()
    frontier = list(seed_urls)

    while frontier:
        url = frontier.pop(0)
        if url not in visited_urls:
            soup = download_page(url)
            if soup:
                filename = f"{url.replace('https://', '').replace('/', '_')}.html"
                save_page(soup, filename)
                visited_urls.add(url)

                if len(visited_urls) % 10 == 0:
                    time.sleep(5)  # Respect website's robots.txt rules

                for link in soup.find_all('a'):
                    href = link.get('href')
                    if href and href.startswith('http'):
                        if not any(href.startswith(prefix) for prefix in visited_urls):
                            frontier.append(href)

        if len(frontier) > max_depth:
            frontier = frontier[:max_depth]

if __name__ == "__main__":
    seed_urls = ['https://example.com']
    crawl_pages(seed_urls)
```

This code provides a basic structure for a web crawler in Python using the `requests` library for HTTP requests and `BeautifulSoup` from `bs4` for parsing HTML. It includes functions to download a page, save it locally, and crawl multiple pages starting from a seed URL. The `crawl_pages` function respects a simple depth limit and checks to avoid revisiting already downloaded URLs. Adjustments may be needed based on specific requirements and website structures.

