def generate_sitemap(start_url):
    sitemap = set()
    visited = set()

    def crawl(url):
        if url not in visited:
            visited.add(url)
            print(f"Crawling {url}")
            html = fetch_page(url)
            if html:
                sitemap.update(extract_links(html))
                for new_url in extract_links(html):
                    crawl(new_url)

    crawl(start_url)
    return sitemap

def save_sitemap(sitemap, filename="sitemap.html"):
