        file.write("<!DOCTYPE html>\n<html>\n<head><title>Sitemap</title></head>\n<body>\n<ul>")
        for url in sorted(sitemap):
            file.write(f"<li><a href=\"{urllib.parse.urljoin(url, '/')}\" target=\"_blank\">{url}</a></li>\n")
