import json

class BuildSystem:
    def __init__(self, config_path):
        self.config_path = config_path
        self.config = self.load_config()

    def load_config(self):
        with open(self.config_path, 'r') as file:
            return json.load(file)

    def run_build_steps(self):
        for step in self.config['build_steps']:
            self.run_step(step)

    def run_step(self, step):
        command = step.get('command')
        if not command:
            raise ValueError("Command not specified in build step")

        output_dir = step.get('output_dir', '.')

        # Create output directory if it doesn't exist
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        print(f"Running command: {command}")
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True, cwd=output_dir)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            print(f"Error running command: {stderr.decode()}")
        else:
            print(f"Command successful: {stdout.decode()}")

if __name__ == "__main__":
    config_path = 'build_config.json'  # Path to the build configuration file
    build_system = BuildSystem(config_path)
    build_system.run_build_steps()
