class WebCacheServer:
    def __init__(self, cache_dir='cache'):
        self.app = Flask(__name__)
        self.cache_dir = cache_dir
        if not os.path.exists(cache_dir):
            os.makedirs(cache_dir)

        @self.app.route('/<path:url>', methods=['GET'])
        def serve_cache(url):
            cache_file = os.path.join(self.cache_dir, url.replace('/', '_'))
            if os.path.exists(cache_file):
                with open(cache_file, 'rb') as f:
                    response_data = f.read()
                    headers = {
                        'Content-Type': 'application/octet-stream',
                        'Last-Modified': time.strftime('%a, %d %b %Y %H:%M:%S GMT', time.gmtime(os.path.getmtime(cache_file))),
                    }
                    return send_from_directory('', '', as_attachment=False, conditional=True, last_modified=time.time(), headers=headers)
            else:
                return 'Not found', 404

        @self.app.after_request
        def add_header(response):
            response.cache_control.max_age = 60 * 60 * 24  # Cache for 24 hours
            return response

    def run(self, host='127.0.0.1', port=5000):
        self.app.run(host=host, port=port)

if __name__ == '__main__':
