from datetime import datetime
from typing import List, Dict

class Contact:
    def __init__(self, name: str, email: str, phone_number: str = '', company: str = '') -> None:
        self.name = name
        self.email = email
        self.phone_number = phone_number
        self.company = company

    @property
    def vcard(self) -> str:
        now = datetime.now().strftime("%Y%m%dT%H%M%SZ")
        lines = [
            "BEGIN:VCARD",
            f"VERSION:3.0",
            f"N:{self.last_name};{self.first_name}",
            f"FN:{self.name}",
            f"UID:{now}",
            "END:VCARD"
        ]

        if self.company:
            lines.append(f"ORG:{self.company}")

        if self.phone_number:
            lines.append(f"TEL;TYPE=WORK,VOICE:{self.phone_number}")

        if self.email:
            lines.append(f"EMAIL;TYPE=PREF,INTERNET:{self.email}")

        return "\n".join(lines)

    @property
    def first_name(self) -> str:
        names = self.name.split()
        return names[0]

    @property
    def last_name(self) -> str:
        names = self.name.split()
        if len(names) > 1:
            return ' '.join(names[1:])
        else:
            return ''

def export_to_vcard(contacts: List[Contact], filename: str) -> None:
